#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

readonly DEFAULT_PORT=4096
# Derived ports land in 4097..4996: above the default, below macOS AirPlay on 5000.
readonly WORKSPACE_PORT_FIRST=4097
readonly WORKSPACE_PORT_COUNT=900
# docker-compose.yml's `name:`, the project of every setup made before names were derived.
readonly LEGACY_PROJECT_NAME="opencode"
# The home volume every repository shared before it was derived per repository. Kept in
# .env only as an explicit opt-in.
readonly SHARED_HOME_VOLUME="opencode_opencode-home"
readonly DEFAULT_UPDATE_HOUR=4
readonly DEFAULT_BASE_IMAGE="debian:trixie-slim"
readonly PYTHON_PROFILE_APT_PACKAGES="build-essential"
readonly HEALTH_TIMEOUT_SECONDS=900
readonly OVERRIDE_FILE="docker-compose.override.yml"
readonly APT_CONFIG_DIR="docker/apt"
readonly DEFAULT_UV_PIP_INDEX_URL="https://pypi.org/simple"
# https only: pip ignores a plain http index unless told --trusted-host. Host, optional port
# and path; no user:password@, the index takes only a URL.
readonly UV_PIP_INDEX_URL_PATTERN='^https://[A-Za-z0-9.-]+(:[0-9]+)?(/[A-Za-z0-9._~%+/-]*)?$'
readonly KNOWN_HOSTS_FILE=".git-ssh/known_hosts"
readonly CONTAINER_GIT_KEY="/run/git-ssh/id"
readonly CONTAINER_KNOWN_HOSTS="/run/git-ssh/known_hosts"
# Hex digits of sha256 in a .venv volume name: 64 bits, out of reach of a forged collision.
readonly VENV_HASH_LENGTH=16
# "VOLUME TARGET" per python project, filled by prepare_venv_overlays, written by
# write_override_file.
VENV_OVERLAYS=()

expand_path() {
  local path="$1"
  printf '%s' "${path/#\~/$HOME}"
}

host_timezone() {
  local link
  link=$(readlink /etc/localtime 2>/dev/null || true)
  case "$link" in
    *zoneinfo/*) printf '%s' "${link##*zoneinfo/}" ;;
    *) printf 'UTC' ;;
  esac
}

generate_password() {
  if command -v openssl >/dev/null 2>&1; then
    openssl rand -hex 24
  else
    od -An -N24 -tx1 /dev/urandom | tr -d ' \n'
  fi
}

# Directory to mount so that an absolute symlink target resolves in the container.
# The parent is mounted so that sibling targets (e.g. many skills in one folder)
# collapse into a single mount; the home directory or / itself is never mounted.
mount_dir_for_target() {
  local target="$1" parent
  parent=$(dirname "$target")
  if [[ "$parent" == "/" || "$parent" == "$HOME" || "$parent" == "$(dirname "$HOME")" ]]; then
    printf '%s' "$target"
  else
    printf '%s' "$parent"
  fi
}

# Prints absolute symlink targets found in the given directories, one per line.
absolute_symlink_targets() {
  local dir link target
  for dir in "$@"; do
    [[ -d "$dir" ]] || continue
    while IFS= read -r link; do
      target=$(readlink "$link")
      [[ "$target" == /* ]] || continue
      if [[ ! -e "$target" ]]; then
        warn "ссылка $link ведёт в $target, а такого пути нет и на хосте; пропускаю" >&2
        continue
      fi
      printf '%s\n' "$target"
    done < <(find "$dir" -maxdepth 2 -type l -not -path '*/node_modules/*')
  done
}

# Reads paths from stdin, prints them sorted and without entries nested in others.
# Sorted bytewise with a trailing slash, so a path's descendants follow it directly: plain
# sort puts /w/a-b between /w/a and /w/a/c, and /w/a/c then passed as not nested.
drop_nested_paths() {
  local path kept=""
  while IFS= read -r path; do
    path="${path%/}"
    if [[ -n "$kept" && "$path/" == "$kept/"* ]]; then
      continue
    fi
    printf '%s\n' "$path"
    kept="$path"
  done < <(sed -e '/^$/d' -e 's|$|/|' | LC_ALL=C sort -u)
}

# workspace_dirs_with WORKSPACE NAME prints, sorted, every directory in WORKSPACE (itself
# included) that holds an entry named NAME. No depth limit; symlinks are not followed, and
# .git, .venv and node_modules are never entered, though they still match as NAME: with
# NAME=.git it lists the repositories, a submodule's or worktree's .git file included.
# The walk is NUL-separated: the agent names the directories, and a newline in a name would
# split it into a path outside WORKSPACE. A path with any control character is skipped with
# a warning on stderr, so the output is one clean path per line.
workspace_dirs_with() {
  local workspace="$1" name="$2" entry dir
  while IFS= read -r -d '' entry; do
    dir="${entry%/*}"
    if [[ "$dir" == *[[:cntrl:]]* ]]; then
      warn "пропускаю $(printf '%q' "$dir"): в имени управляющие символы" >&2
      continue
    fi
    [[ "$dir" == "$workspace" || "$dir" == "$workspace/"* ]] || continue
    printf '%s\n' "$dir"
  done < <(find "$workspace" -mindepth 1 \
    \( -name .git -o -name .venv -o -name node_modules \) -prune -name "$name" -print0 \
    -o -name "$name" -print0) | LC_ALL=C sort
}

# python_projects WORKSPACE prints the top python projects in WORKSPACE: directories with a
# pyproject.toml and none in a parent inside WORKSPACE. A subproject under another
# pyproject.toml gets no .venv overlay of its own.
python_projects() {
  workspace_dirs_with "$1" pyproject.toml | drop_nested_paths
}

copy_to_clipboard() {
  if command -v pbcopy >/dev/null 2>&1; then pbcopy
  elif command -v wl-copy >/dev/null 2>&1; then wl-copy
  elif command -v xclip >/dev/null 2>&1; then xclip -selection clipboard
  else return 1
  fi
}

# Prints ports the opencode config reaches on the loopback (127.0.0.1, localhost,
# [::1]), comma-separated. The container's own server port is excluded.
config_loopback_ports() {
  local dir="$1"
  { grep -ohE '(127\.0\.0\.1|localhost|\[::1\]):[0-9]+' "$dir"/*.json "$dir"/*.jsonc 2>/dev/null || true; } \
    | sed 's/.*://' | sort -un | grep -vx "$DEFAULT_PORT" | paste -sd, - || true
}

# confirm_default 1|0 "question" is a yes/no gate whose Enter answer is the saved one:
# 1 shows [Y/n] and Enter means yes, 0 shows [y/N] and Enter means no.
confirm_default() {
  local default="$1" hint="y/N" reply=""
  [[ "$default" == 1 ]] && hint="Y/n"
  printf '  %s? %s [%s]%s ' "$YELLOW" "$2" "$hint" "$RESET"
  read -r reply || true
  if [[ -z "$reply" ]]; then
    [[ "$default" == 1 ]]
    return
  fi
  [[ "$reply" =~ ^[Yy] ]]
}

# Prints 1 when git push over ssh was configured by an earlier run, else 0.
saved_git_ssh_flag() {
  local command
  command=$(_existing GIT_SSH_COMMAND || true)
  if [[ -n "$command" && "$command" != "ssh" ]]; then printf '1'; else printf '0'; fi
}

# Prints 1 when the python profile was enabled by an earlier run, else 0.
saved_python_profile_flag() {
  if [[ "$(_existing INSTALL_UV || true)" == "1" ]]; then printf '1'; else printf '0'; fi
}

# drop_env KEY removes KEY from ENV_FILE, keeping the file's mode like write_env does.
drop_env() {
  local key="$1" tmp
  [[ -f "$ENV_FILE" ]] && grep -qE "^${key}=" "$ENV_FILE" || return 0
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf '  %s✓ removed%s %s from %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# Asks whether this is a python project, with the saved answer as the Enter default, and
# writes INSTALL_UV (1/0). With the profile on, also asks the PyPI index uv is installed
# from and writes UV_PIP_INDEX_URL. Drops UV_REGISTRY, left by the uv-image setup.
# Not a yes/no return on purpose: inside `if` set -e is off, and an EOF in the index loop
# would spin forever instead of stopping the wizard.
configure_python_profile() {
  local saved question
  saved=$(saved_python_profile_flag)
  if [[ "$saved" == 1 ]]; then
    question="Оставить питон-профиль?"
  else
    question="В рабочей папке есть питон-проекты? Включить питон-профиль?"
  fi
  drop_env UV_REGISTRY
  if ! confirm_default "$saved" "$question"; then
    write_env INSTALL_UV 0
    return 0
  fi
  write_env INSTALL_UV 1
  while true; do
    ask UV_PIP_INDEX_URL "PyPI-индекс, откуда ставится uv [$DEFAULT_UV_PIP_INDEX_URL], корпоративный, если pypi.org закрыт:" \
      || return 1
    UV_PIP_INDEX_URL="${UV_PIP_INDEX_URL:-$DEFAULT_UV_PIP_INDEX_URL}"
    [[ "$UV_PIP_INDEX_URL" =~ $UV_PIP_INDEX_URL_PATTERN ]] && break
    warn "индекс: https-адрес без логина, например https://nexus.example.corp/repository/pypi/simple"
  done
  write_env UV_PIP_INDEX_URL "$UV_PIP_INDEX_URL"
}

# Prints 1 when host ports should be forwarded by default: an earlier run saved some, or
# this is the first run and the config reaches FOUND ports on the loopback. Else 0.
saved_host_ports_flag() {
  local found="$1"
  if [[ -n "$(_existing HOST_LOOPBACK_PORTS || true)" ]]; then
    printf '1'
  elif [[ -n "$found" ]] && ! grep -qE '^HOST_LOOPBACK_PORTS=' "$ENV_FILE" 2>/dev/null; then
    printf '1'
  else
    printf '0'
  fi
}

# Asks which host ports the container forwards from its loopback and writes
# HOST_LOOPBACK_PORTS. With FOUND ports (from config_loopback_ports) one yes/no forwards
# exactly them; without, a yes asks for the list. A no forwards nothing and asks nothing
# else. Not a yes/no return, for the same reason as configure_python_profile.
configure_host_ports() {
  local found="$1" ports=""
  if [[ -n "$found" ]]; then
    confirm_default "$(saved_host_ports_flag "$found")" "Пробросить эти порты?" && ports="$found"
  elif confirm_default "$(saved_host_ports_flag "")" "Пробросить порты хоста в контейнер?"; then
    while true; do
      ask HOST_LOOPBACK_PORTS "Порты через запятую, например 17321,8080:" || return 1
      ports="${HOST_LOOPBACK_PORTS// /}"
      [[ "$ports" =~ ^[0-9]+(,[0-9]+)*$ ]] && break
      warn "нужен список чисел через запятую, например 17321,8080"
    done
  fi
  write_env HOST_LOOPBACK_PORTS "$ports"
}

# True when a docker endpoint (unix:///path/to/docker.sock) lives in colima's home.
endpoint_is_colima() {
  local path="${1#unix://}"
  [[ "$path" == "$HOME/.colima/"* || "$path" == "${COLIMA_HOME:-$HOME/.colima}/"* ]]
}

context_endpoint() {
  docker context inspect --format '{{.Endpoints.docker.Host}}' "$1" 2>/dev/null || true
}

# Prints the engine a docker context points at: colima, orbstack, docker-desktop or other.
# colima names the context of profile P "colima-P" and the default profile's plain "colima";
# a context named otherwise (or `default` with DOCKER_HOST) is recognised by its endpoint.
engine_for_context() {
  case "$1" in
    colima|colima-*) printf 'colima'; return ;;
    orbstack) printf 'orbstack'; return ;;
    desktop-linux) printf 'docker-desktop'; return ;;
  esac
  if endpoint_is_colima "$(context_endpoint "$1")"; then printf 'colima'; else printf 'other'; fi
}

# Prints the Docker engine behind the current docker CLI. DOCKER_HOST overrides contexts.
# The context works even when the daemon is down; the daemon's own name is the fallback.
detect_engine() {
  local engine os
  if [[ -n "${DOCKER_HOST:-}" ]]; then
    if endpoint_is_colima "$DOCKER_HOST"; then engine=colima; else engine=other; fi
  else
    engine=$(engine_for_context "$(docker context show 2>/dev/null || true)")
  fi
  if [[ "$engine" != "other" ]]; then
    printf '%s' "$engine"
    return
  fi
  os=$(docker info --format '{{.OperatingSystem}}' 2>/dev/null || true)
  case "$os" in
    *OrbStack*) printf 'orbstack' ;;
    *"Docker Desktop"*) printf 'docker-desktop' ;;
    *)
      if [[ -z "$os" ]] && command -v colima >/dev/null 2>&1; then
        printf 'colima'
      else
        printf 'other'
      fi
      ;;
  esac
}

# The one place that knows each engine. Sets ENGINE_TITLE, ENGINE_IS_COLIMA (1/0) and
# ENGINE_MOUNT_NOTE (lines shown for WORKSPACE, colima has its own check instead).
engine_profile() {
  local engine="$1" workspace="$2"
  ENGINE_IS_COLIMA=0
  ENGINE_MOUNT_NOTE=""
  case "$engine" in
    colima)
      ENGINE_TITLE="colima"
      ENGINE_IS_COLIMA=1
      ;;
    orbstack)
      ENGINE_TITLE="OrbStack"
      ENGINE_MOUNT_NOTE="✓ OrbStack пробрасывает любой путь хоста, $workspace контейнер увидит."
      ;;
    docker-desktop)
      ENGINE_TITLE="Docker Desktop"
      ENGINE_MOUNT_NOTE="Docker Desktop пробрасывает пути из Settings → Resources → File sharing."$'\n'"По умолчанию там /Users, /Volumes, /private, /tmp. Рабочую папку в другом месте добавь туда."
      ;;
    *)
      ENGINE_TITLE="docker-совместимый движок"
      ENGINE_MOUNT_NOTE="Движок не опознал. Если контейнер не увидит $workspace, разреши движку доступ к этой папке."
      ;;
  esac
}

# Sets ENGINE (and ENGINE_CONTEXT) to the engine this run uses. The current docker context
# decides, unless the saved engine in ENV_FILE differs or several engine contexts exist:
# then the user picks, with the saved engine as the Enter default. A pick of another
# context is exported as DOCKER_CONTEXT for the rest of the run.
choose_engine() {
  local current saved name engine i default_index=0 pick reply
  local names=() engines=()
  current=$(docker context show 2>/dev/null || true)
  ENGINE=$(detect_engine)
  ENGINE_CONTEXT="$current"
  [[ -z "${DOCKER_HOST:-}" ]] || return 0
  saved=$(_existing DOCKER_ENGINE || true)
  if [[ -n "$saved" && "$saved" != "$ENGINE" ]]; then
    warn "в $ENV_FILE сохранён движок $saved, а docker сейчас смотрит в $ENGINE (контекст $current)."
  fi

  names+=("$current"); engines+=("$ENGINE")
  while IFS= read -r name; do
    [[ -n "$name" && "$name" != "$current" ]] || continue
    engine=$(engine_for_context "$name")
    [[ "$engine" != "other" ]] || continue
    names+=("$name"); engines+=("$engine")
  done < <(docker context ls --format '{{.Name}}' 2>/dev/null || true)
  (( ${#names[@]} > 1 )) || return 0

  for i in "${!names[@]}"; do
    [[ -n "$saved" && "${engines[$i]}" == "$saved" ]] && { default_index=$i; break; }
  done
  say "Несколько движков docker, какой использовать?"
  for i in "${!names[@]}"; do
    step "$((i + 1)). ${names[$i]} (${engines[$i]})$([[ $i -eq $default_index ]] && printf ' [Enter]')"
  done
  while true; do
    printf '  %s? Номер:%s ' "$YELLOW" "$RESET"
    read -r reply || reply=""
    pick="${reply:-$((default_index + 1))}"
    [[ "$pick" =~ ^[0-9]+$ ]] && (( pick >= 1 && pick <= ${#names[@]} )) && break
    warn "нужен номер от 1 до ${#names[@]}"
  done
  ENGINE="${engines[$((pick - 1))]}"
  ENGINE_CONTEXT="${names[$((pick - 1))]}"
  if [[ "$ENGINE_CONTEXT" != "$current" ]]; then
    export DOCKER_CONTEXT="$ENGINE_CONTEXT"
    warn "это только для визарда. Свои docker compose команды запускай после: docker context use $ENGINE_CONTEXT"
  fi
}

# The colima profile behind the current docker context: "colima-P" or an endpoint
# <colima home>/P/docker.sock names it; anything else is the default profile.
colima_profile() {
  local context endpoint path
  if [[ -n "${DOCKER_HOST:-}" ]]; then
    endpoint="$DOCKER_HOST"
  else
    context=$(docker context show 2>/dev/null || true)
    case "$context" in
      colima-*) printf '%s' "${context#colima-}"; return ;;
    esac
    endpoint=$(context_endpoint "$context")
  fi
  path="${endpoint#unix://}"
  path="${path#"$HOME"/.colima/}"
  path="${path#"${COLIMA_HOME:-$HOME/.colima}"/}"
  if [[ "$path" == */docker.sock && "$path" != "${endpoint#unix://}" ]]; then
    printf '%s' "${path%%/*}"
  else
    printf 'default'
  fi
}

colima_running() {
  colima status --profile "$COLIMA_PROFILE" >/dev/null 2>&1
}

# Single-quotes a string for a POSIX sh.
sh_quote() {
  local quote="'" escaped="'\\''"
  printf "'%s'" "${1//$quote/$escaped}"
}

# Whether WORKSPACE inside the colima VM is the host folder and not an empty directory that
# docker created on a previous bind of an unmounted path. Probes one regular file of the
# host folder: the folder may have no .git of its own, and a directory proves nothing,
# since docker creates the directories of nested .venv mount points in the VM.
# Returns 0 seen, 1 not seen, 2 can't tell (the host folder holds no file).
# The probe goes to the VM's sh on stdin: lima versions differ in whether `colima ssh`
# quotes its arguments, so a quoted argument is either right or quoted twice.
colima_sees_workspace() {
  local marker
  marker=$(find "$1" \( -name .venv -o -name node_modules \) -prune -o -type f -print -quit)
  [[ -n "$marker" ]] || return 2
  printf 'test -e %s\n' "$(sh_quote "$marker")" \
    | colima ssh --profile "$COLIMA_PROFILE" -- sh >/dev/null 2>&1 || return 1
}

# Sets COLIMA_CMD to `colima <subcommand>` for the chosen profile.
colima_command() {
  COLIMA_CMD=(colima "$1")
  [[ "$COLIMA_PROFILE" == "default" ]] || COLIMA_CMD+=(--profile "$COLIMA_PROFILE")
}

# Sets COLIMA_START to the start command that makes WORKSPACE visible in the VM.
# `colima start --mount` replaces the whole mount list, including the default
# $HOME that holds the configs the container mounts, so $HOME is always passed.
# colima refuses overlapping mounts, so a WORKSPACE inside $HOME is covered by
# $HOME alone and gets no mount of its own.
set_colima_start() {
  local workspace="$1"
  colima_command start
  COLIMA_START=("${COLIMA_CMD[@]}")
  if [[ "$workspace" != "$HOME" && "$workspace" != "$HOME"/* ]]; then
    COLIMA_START+=(--mount "$workspace:w")
  fi
  COLIMA_START+=(--mount "$HOME:w")
}

# Prints a command array as a copy-pasteable shell line.
shell_line() {
  local line
  printf -v line '%q ' "$@"
  printf '%s' "${line% }"
}

# Stage "Репозиторий внутри движка" for colima: gets WORKSPACE visible in the VM or fails.
ensure_colima_workspace() {
  local workspace="$1" seen=0 running_containers
  if ! command -v colima >/dev/null 2>&1; then
    warn "docker смотрит в контекст colima, а команды colima нет. Поставь её: brew install colima"
    return 1
  fi
  say "colima пробрасывает в свою VM только явно указанные папки, по умолчанию домашнюю."
  set_colima_start "$workspace"
  if ! colima_running; then
    say "colima не запущена. Запусти её так, чтобы рабочая папка была видна в VM:"
    step "$(shell_line "${COLIMA_START[@]}")"
    if confirm "Запустить сейчас?"; then
      "${COLIMA_START[@]}" || true
    else
      pause "Выполни команду в другом терминале и нажми Enter"
    fi
  else
    colima_sees_workspace "$workspace" || seen=$?
    if (( seen == 1 )); then
      colima_command stop
      warn "$workspace не примонтирован в VM colima, контейнер увидит пустую папку."
      say "Нужен перезапуск colima с этой папкой в mount:"
      step "$(shell_line "${COLIMA_CMD[@]}") && $(shell_line "${COLIMA_START[@]}")"
      running_containers=$(docker ps -q 2>/dev/null | wc -l | tr -d ' ')
      warn "colima stop остановит все контейнеры в этой VM (сейчас запущено: $running_containers), не только opencode."
      note "Если у тебя в colima свои mount, допиши их в команду: --mount заменяет весь список."
      if confirm "Перезапустить colima сейчас?"; then
        if "${COLIMA_CMD[@]}"; then "${COLIMA_START[@]}" || true; fi
      else
        pause "Выполни команду в другом терминале и нажми Enter"
      fi
    fi
  fi
  if ! colima_running || ! docker info >/dev/null 2>&1; then
    warn "colima не отвечает. Запусти её командой выше и запусти визард снова."
    return 1
  fi
  seen=0
  colima_sees_workspace "$workspace" || seen=$?
  case "$seen" in
    0) say "✓ $workspace виден внутри VM colima" ;;
    2) warn "в $workspace нет ни одного файла, поэтому проверить, видна ли она в VM colima, не могу." ;;
    *)
      warn "$workspace всё ещё не виден в VM colima. Перезапусти её командой выше и запусти визард снова."
      return 1
      ;;
  esac
}

wait_until_ready() {
  local url="$1" waited=0 step_seconds=5
  printf '  ждём сервер'
  while (( waited < HEALTH_TIMEOUT_SECONDS )); do
    if curl -fsS -o /dev/null -m 5 "$url" 2>/dev/null; then
      printf ' готово\n'
      return 0
    fi
    printf '.'
    sleep "$step_seconds"
    waited=$((waited + step_seconds))
  done
  printf '\n'
  return 1
}

# Prints private keys in ~/.ssh (files whose first line is a PEM/OpenSSH private key header).
ssh_private_keys() {
  local file
  for file in "$HOME"/.ssh/*; do
    [[ -f "$file" && "$file" != *.pub ]] || continue
    if head -n1 "$file" 2>/dev/null | grep -q -- '-----BEGIN .*PRIVATE KEY-----'; then
      printf '%s\n' "$file"
    fi
  done
}

# Succeeds when the key opens with an empty passphrase. There is no ssh-agent in the
# container, so a key with a passphrase can't be used there at all.
key_has_no_passphrase() {
  ssh-keygen -y -P "" -f "$1" </dev/null >/dev/null 2>&1
}

# Prints "host port" of an ssh git remote (ssh://[user@]host[:port]/path or the scp-like
# [user@]host:path). Fails for https and local remotes. The host is validated because
# it goes to ssh-keyscan as an argument.
ssh_remote_host() {
  local url="$1" authority host port=""
  case "$url" in
    ssh://* | git+ssh://* | ssh+git://*)
      authority="${url#*://}"
      authority="${authority%%/*}"
      authority="${authority##*@}"
      host="${authority%%:*}"
      [[ "$authority" == *:* ]] && port="${authority#*:}"
      ;;
    *://*) return 1 ;;
    *:*)
      authority="${url%%:*}"
      [[ "$authority" == */* ]] && return 1
      host="${authority##*@}"
      ;;
    *) return 1 ;;
  esac
  port="${port:-22}"
  [[ "$host" =~ ^[A-Za-z0-9][A-Za-z0-9._-]*$ && "$port" =~ ^[0-9]+$ ]] || return 1
  printf '%s %s\n' "$host" "$port"
}

# Name of the repository's origin remote, or of its first remote when there is no origin.
workspace_remote_name() {
  local workspace="$1" remote
  remote=$(git -C "$workspace" remote 2>/dev/null | grep -x origin || git -C "$workspace" remote 2>/dev/null | head -n1) || return 1
  [[ -n "$remote" ]] || return 1
  printf '%s' "$remote"
}

# Push URL of the remote workspace_remote_name picks.
workspace_remote_url() {
  local workspace="$1" remote
  remote=$(workspace_remote_name "$workspace") || return 1
  git -C "$workspace" remote get-url --push "$remote"
}

# Prints "hostname port user" as ssh resolves HOST with ~/.ssh/config applied (`ssh -G`).
# Fails when ssh can't tell.
ssh_resolved() {
  local key value hostname="" port="" user=""
  command -v ssh >/dev/null 2>&1 || return 1
  while read -r key value; do
    case "$key" in
      hostname) hostname="$value" ;;
      port) port="$value" ;;
      user) user="$value" ;;
    esac
  done < <(ssh -G "$1" 2>/dev/null || true)
  [[ -n "$hostname" ]] || return 1
  printf '%s %s %s\n' "$hostname" "${port:-22}" "$user"
}

# Prints the remote URL spelled with the real host and port, for `git remote set-url`.
# The user comes from the URL, else from FALLBACK_USER. Usage: URL HOST PORT FALLBACK_USER.
explicit_remote_url() {
  local url="$1" host="$2" port="$3" fallback_user="$4" scheme authority path user
  case "$url" in
    *://*) scheme="ssh"; authority="${url#*://}"; path="/${authority#*/}"; authority="${authority%%/*}" ;;
    *) scheme="scp"; authority="${url%%:*}"; path="${url#*:}" ;;
  esac
  if [[ "$authority" == *@* ]]; then user="${authority%@*}"; else user="${fallback_user:-git}"; fi
  if [[ "$scheme" == "scp" && "$port" == "22" ]]; then
    printf '%s@%s:%s' "$user" "$host" "$path"
    return
  fi
  [[ "$path" == /* ]] || path="/~/$path"
  [[ "$scheme" == "ssh" && "$port" == "22" ]] && port=""
  printf 'ssh://%s@%s%s%s' "$user" "$host" "${port:+:$port}" "$path"
}

# Prints the absolute, symlink-resolved path of a key typed by the user (relative paths are
# taken from the current directory). Fails with a warning on characters that would break the
# compose mount line or the container's ssh command.
normalize_key_path() {
  local path dir
  path=$(expand_path "$1")
  [[ "$path" == /* ]] || path="$PWD/$path"
  dir=$(dirname "$path")
  if [[ -d "$dir" ]]; then
    path="$(cd "$dir" && pwd -P)/$(basename "$path")"
  fi
  case "$path" in
    *\"* | *\\* | *\$* | *:* | *$'\n'*)
      warn "в пути к ключу нельзя \" \\ \$ : и переводы строк, иначе он сломает mount: $path" >&2
      return 1
      ;;
  esac
  printf '%s' "$path"
}

# Prints an absolute PATH with every symlink resolved, the last component included.
resolved_path() {
  local path="$1" target hops=0
  while [[ -L "$path" ]] && (( hops < 40 )); do
    target=$(readlink "$path")
    [[ "$target" == /* ]] || target="$(dirname "$path")/$target"
    path="$target"
    hops=$((hops + 1))
  done
  if [[ -d "$(dirname "$path")" ]]; then
    path="$(cd "$(dirname "$path")" && pwd -P)/$(basename "$path")"
  fi
  printf '%s' "$path"
}

# path_inside PATH DIR: PATH is DIR or lies under it. Both resolved; the trailing slash keeps
# /w/a-b out of /w/a.
path_inside() {
  local path="${1%/}" dir="${2%/}"
  [[ "$path/" == "$dir/"* ]]
}

paths_overlap() {
  path_inside "$1" "$2" || path_inside "$2" "$1"
}

# choose_workspace HARNESS asks for the workspace folder until it gets an existing one that
# doesn't overlap HARNESS (the resolved harness checkout) and sets WORKSPACE to its resolved
# path. The agent writes the whole workspace folder; the harness holds the compose files,
# scripts/setup.sh, known_hosts and .env, which the host runs or reads on the next `up`.
choose_workspace() {
  local harness="$1"
  while true; do
    ask WORKSPACE "Путь к рабочей папке:" || return 1
    WORKSPACE=$(expand_path "${WORKSPACE:-}")
    if [[ -z "$WORKSPACE" || ! -d "$WORKSPACE" ]]; then
      warn "папки '$WORKSPACE' нет"
      continue
    fi
    WORKSPACE=$(cd "$WORKSPACE" && pwd -P)
    if paths_overlap "$WORKSPACE" "$harness"; then
      warn "$WORKSPACE и харнесс $harness вложены друг в друга. Агент перепишет compose-файлы"
      warn "и скрипты харнесса и прочитает его .env, а следующий up выполнит это на хосте."
      continue
    fi
    return 0
  done
}

lowercase() {
  printf '%s' "$1" | tr '[:upper:]' '[:lower:]'
}

# The name ssh-keyscan writes and ssh looks up in known_hosts: HOST, or [HOST]:PORT off 22.
known_hosts_name() {
  if [[ "$2" == 22 ]]; then printf '%s' "$1"; else printf '[%s]:%s' "$1" "$2"; fi
}

# "host port repo" per ssh host, repo being the first repository that pushes there, and the
# remote URLs that push there, filled by collect_ssh_hosts.
SSH_HOSTS=()
SSH_REMOTES=()

# collect_ssh_hosts WORKSPACE fills SSH_HOSTS with the hosts of the remotes of every repository
# in WORKSPACE, each host once (lowercased, as ssh looks it up) with the first repository on
# it, and SSH_REMOTES with those remotes. A repository without a remote, with a non-ssh remote
# or with an ~/.ssh/config alias is skipped with a message: the container has no ~/.ssh/config.
collect_ssh_hosts() {
  local workspace="$1" repo url host_port host port resolved real_host real_port real_user entry known
  SSH_HOSTS=()
  SSH_REMOTES=()
  while IFS= read -r repo; do
    if ! url=$(workspace_remote_url "$repo"); then
      note "в $repo нет git remote, пропускаю"
      continue
    fi
    # The agent writes the remote: a newline or an escape sequence would forge wizard output.
    if [[ "$url" == *[[:cntrl:]]* ]]; then
      warn "$repo: в remote управляющие символы, пропускаю. Проверь его: git -C $(sh_quote "$repo") remote -v"
      continue
    fi
    if ! host_port=$(ssh_remote_host "$url"); then
      warn "$repo: remote $url не ssh, пропускаю. Пока поддержан только push по ssh."
      continue
    fi
    read -r host port <<< "$host_port"
    if resolved=$(ssh_resolved "$host"); then
      read -r real_host real_port real_user <<< "$resolved"
      if [[ "$(lowercase "$real_host")" != "$(lowercase "$host")" ]]; then
        warn "$repo: $host — псевдоним из ~/.ssh/config (на самом деле $real_host:$real_port). В контейнере этого конфига нет."
        warn "Remote через псевдоним не поддержан, пропускаю. Перепиши его на настоящий хост:"
        step "$(shell_line git -C "$repo" remote set-url "$(workspace_remote_name "$repo")" \
          "$(explicit_remote_url "$url" "$real_host" "$real_port" "$real_user")")"
        continue
      fi
    fi
    SSH_REMOTES+=("$url")
    host=$(lowercase "$host")
    known=0
    for entry in ${SSH_HOSTS[@]+"${SSH_HOSTS[@]}"}; do
      [[ "$entry" == "$host $port "* ]] && known=1
    done
    (( known )) || SSH_HOSTS+=("$host $port $repo")
  done < <(workspace_dirs_with "$workspace" .git)
}

# Interactive part of the "Git-доступ по SSH" stage. One key for the whole workspace folder;
# known_hosts gets every ssh host of its repositories. A host already in $KNOWN_HOSTS_FILE is
# kept as is, a new one is written only after its fingerprint is confirmed. On success appends
# the key and known_hosts mounts to extra_mounts and sets git_ssh_command; fails when the user
# skips or no host ends up in known_hosts.
configure_git_ssh() {
  local keys key choice scan entry host port name kept planned remote
  if ! command -v git >/dev/null 2>&1 || ! command -v ssh-keyscan >/dev/null 2>&1; then
    warn "на хосте нет git или ssh-keyscan, настроить push не получится"
    return 1
  fi
  collect_ssh_hosts "$WORKSPACE"
  if (( ${#SSH_HOSTS[@]} == 0 )); then
    warn "в $WORKSPACE нет репозиториев с ssh-remote, пушить некуда"
    return 1
  fi
  say "Хосты, куда пушат репозитории рабочей папки:"
  for entry in "${SSH_HOSTS[@]}"; do
    read -r host port _ <<< "$entry"
    step "$host, порт $port"
  done

  keys=$(ssh_private_keys)
  if [[ -z "$keys" ]]; then
    warn "в $HOME/.ssh нет приватных ключей. Создай deploy-ключ: ssh-keygen -t ed25519 -N '' -f ~/.ssh/id_deploy"
    return 1
  fi
  while true; do
    printf '\n'
    say "Приватные ключи в $HOME/.ssh:"
    nl -w3 -s'. ' <<< "$keys" | while IFS= read -r line; do say "$line"; done
    ask GIT_SSH_KEY "Номер или путь к ключу («-» — пропустить этот шаг):" || return 1
    choice="${GIT_SSH_KEY:-}"
    [[ "$choice" == "-" ]] && return 1
    if [[ "$choice" =~ ^[0-9]+$ ]]; then
      key=$(sed -n "${choice}p" <<< "$keys")
    else
      key="$choice"
    fi
    if [[ -z "$key" ]]; then
      warn "ключа '$choice' нет"
      continue
    fi
    key=$(normalize_key_path "$key") || continue
    if [[ ! -f "$key" ]]; then
      warn "ключа '$choice' нет"
      continue
    fi
    if path_inside "$(resolved_path "$key")" "$WORKSPACE"; then
      warn "ключ $key лежит в рабочей папке: агент подменит его ссылкой на любой файл хоста,"
      warn "и следующий up смонтирует тот файл в контейнер. Положи ключ вне рабочей папки."
      continue
    fi
    if key_has_no_passphrase "$key"; then
      break
    fi
    printf '\n'
    warn "на ключе $key стоит passphrase."
    warn "В контейнере нет ssh-agent, ввести её некому: push этим ключом не пройдёт."
    say "Заведи отдельный deploy-ключ без passphrase и добавь его в GitLab/GitHub с правом записи:"
    say "  ssh-keygen -t ed25519 -N '' -f ~/.ssh/id_deploy"
  done
  write_env GIT_SSH_KEY "$key"
  printf '\n'
  say "Один ключ на всю рабочую папку. Добавь его публичную часть (ssh-keygen -y -f $key)"
  say "deploy-ключом с правом записи в каждый GitLab-проект, куда пушит агент:"
  for remote in "${SSH_REMOTES[@]}"; do step "$remote"; done
  note "Визард это не проверяет: без ключа в проекте push туда не пройдёт."

  # Built aside and written only when at least one host made it, so a refusal never leaves a
  # half-written or emptied known_hosts behind.
  planned=$(mktemp)
  for entry in "${SSH_HOSTS[@]}"; do
    read -r host port _ <<< "$entry"
    name=$(known_hosts_name "$host" "$port")
    printf '\n'
    if [[ -f "$KNOWN_HOSTS_FILE" ]] \
      && kept=$(ssh-keygen -F "$name" -f "$KNOWN_HOSTS_FILE" 2>/dev/null | grep -v '^#'); then
      printf '%s\n' "$kept" >> "$planned"
      say "✓ $name уже в $KNOWN_HOSTS_FILE, сверка была раньше"
      continue
    fi
    step "ssh-keyscan $host:$port"
    scan=$(ssh-keyscan -T 10 -p "$port" "$host" 2>/dev/null || true)
    if [[ -z "$scan" ]]; then
      warn "хост $host:$port не ответил на ssh-keyscan, в known_hosts его не будет"
      SKIPPED+=("known_hosts: $host:$port не ответил, push туда не пройдёт; запусти визард снова")
      continue
    fi
    say "Ключи хоста $name. Сверь fingerprint с опубликованным у провайдера (у GitHub и"
    say "GitLab он есть в документации) или спроси у админа сервера:"
    ssh-keygen -lf - <<< "$scan" | while IFS= read -r line; do step "$line"; done
    if ! confirm "Fingerprint совпадает?"; then
      warn "fingerprint $name не подтверждён, в known_hosts его не пишу"
      SKIPPED+=("known_hosts: fingerprint $host:$port не подтверждён, push туда не пройдёт")
      continue
    fi
    printf '%s\n' "$scan" >> "$planned"
  done
  if [[ ! -s "$planned" ]]; then
    rm -f "$planned"
    warn "ни один хост не попал в known_hosts, $KNOWN_HOSTS_FILE не трогаю"
    return 1
  fi
  if ! { mkdir -p "$(dirname "$KNOWN_HOSTS_FILE")" && cat "$planned" > "$KNOWN_HOSTS_FILE"; }; then
    rm -f "$planned"
    warn "не смог записать $KNOWN_HOSTS_FILE"
    return 1
  fi
  rm -f "$planned"
  say "✓ записал $KNOWN_HOSTS_FILE"

  extra_mounts+=("$key:$CONTAINER_GIT_KEY" "$PWD/$KNOWN_HOSTS_FILE:$CONTAINER_KNOWN_HOSTS")
  git_ssh_command="ssh -i $CONTAINER_GIT_KEY -o IdentitiesOnly=yes -o BatchMode=yes -o UserKnownHostsFile=$CONTAINER_KNOWN_HOSTS"
}

# compose_escape VALUE prints VALUE for the inside of a YAML double-quoted string that compose
# takes literally: \ and " escaped for YAML, $ doubled against compose interpolation.
compose_escape() {
  local value="$1"
  value="${value//\\/\\\\}"
  value="${value//\"/\\\"}"
  value="${value//\$/\$\$}"
  printf '%s' "$value"
}

# write_override_file FILE MOUNT... writes the per-machine read-only mounts and the .venv
# volume of every python project in VENV_OVERLAYS as a compose override. The volumes get
# explicit names, so compose doesn't prefix them with the project. The image build gets the
# mount points (VENV_MOUNT_POINTS, one per line): a fresh volume copies the owner of its
# mount point from the image, and only a point the image created is owned by opencode.
write_override_file() {
  local file="$1" mount overlay mount_points=""
  shift
  for overlay in ${VENV_OVERLAYS[@]+"${VENV_OVERLAYS[@]}"}; do
    mount_points+="${mount_points:+\\n}$(compose_escape "${overlay#* }")"
  done
  {
    printf '# Generated by scripts/setup.sh. Per-machine read-only mounts and the container .venv\n'
    printf '# of every python project (ADR 0003). Re-run the wizard after cloning a new one.\n'
    printf 'services:\n  opencode:\n'
    if [[ -n "$mount_points" ]]; then
      printf '    build:\n      args:\n        VENV_MOUNT_POINTS: "%s"\n' "$mount_points"
    fi
    printf '    volumes:\n'
    for mount in "$@"; do
      printf '      - "%s:ro"\n' "$(compose_escape "$mount")"
    done
    for overlay in ${VENV_OVERLAYS[@]+"${VENV_OVERLAYS[@]}"}; do
      printf '      - type: volume\n        source: %s\n        target: "%s"\n' \
        "${overlay%% *}" "$(compose_escape "${overlay#* }")"
    done
    if (( ${#VENV_OVERLAYS[@]} )); then
      printf 'volumes:\n'
      for overlay in "${VENV_OVERLAYS[@]}"; do
        printf '  %s:\n    name: %s\n' "${overlay%% *}" "${overlay%% *}"
      done
    fi
  } > "$file"
}

# warn_lost_overlays FILE lists the python projects whose .venv volume FILE declares and
# VENV_OVERLAYS no longer has: after a rewrite of FILE the container's uv sync writes their host
# .venv. A pyproject.toml planted above them, in the workspace root say, drops them that way.
# The paths are shown as FILE holds them, compose-escaped.
warn_lost_overlays() {
  local file="$1" overlay target kept="" lost=()
  for overlay in ${VENV_OVERLAYS[@]+"${VENV_OVERLAYS[@]}"}; do
    kept+="$(compose_escape "${overlay#* }")"$'\n'
  done
  while IFS= read -r target; do
    grep -qxF -- "$target" <<< "$kept" || lost+=("$target")
  done < <(sed -n 's/^        target: "\(.*\)"$/\1/p' "$file")
  (( ${#lost[@]} )) || return 0
  warn "эти питон-проекты теряют свой .venv в контейнере, uv sync оттуда перепишет их хостовый .venv:"
  for target in "${lost[@]}"; do step "${target%/.venv}"; done
  warn "Если ты их не убирал, ищи pyproject.toml над ними, например в корне рабочей папки."
}

# apply_override MOUNT... brings $OVERRIDE_FILE in line with the mounts and VENV_OVERLAYS.
# An up-to-date file is left as is without a question. Returns 1 when the user declined to
# overwrite an existing file, so the old file still stands, or when it couldn't be written.
apply_override() {
  local planned
  if (( $# == 0 && ${#VENV_OVERLAYS[@]} == 0 )); then
    say "Дополнительных папок и питон-проектов нет, $OVERRIDE_FILE не нужен."
    return 0
  fi
  planned=$(mktemp)
  if ! write_override_file "$planned" "$@"; then
    rm -f "$planned"
    warn "не смог собрать $OVERRIDE_FILE"
    return 1
  fi
  if [[ -f "$OVERRIDE_FILE" ]] && ! cmp -s "$planned" "$OVERRIDE_FILE"; then
    warn_lost_overlays "$OVERRIDE_FILE"
  fi
  if [[ -f "$OVERRIDE_FILE" ]] && cmp -s "$planned" "$OVERRIDE_FILE"; then
    say "✓ $OVERRIDE_FILE уже такой, как нужно"
  elif [[ -f "$OVERRIDE_FILE" ]] && ! confirm "$OVERRIDE_FILE уже есть. Перезаписать?"; then
    rm -f "$planned"
    SKIPPED+=("$OVERRIDE_FILE оставлен как был; проверь, что в нём есть нужные папки")
    if (( ${#VENV_OVERLAYS[@]} )); then
      SKIPPED+=("в старом $OVERRIDE_FILE может не быть .venv-volume части питон-проектов: контейнерный uv sync перезапишет их хостовый .venv")
    fi
    return 1
  elif ! cat "$planned" > "$OVERRIDE_FILE"; then
    rm -f "$planned"
    warn "не смог записать $OVERRIDE_FILE"
    return 1
  else
    say "✓ записал $OVERRIDE_FILE"
  fi
  rm -f "$planned"
}

# save_git_ssh_command COMMAND APPLIED writes GIT_SSH_COMMAND to ENV_FILE only when the
# override with the key mounts was applied (APPLIED=1); otherwise the old value stays, so
# .env never points git at a key the container doesn't have.
save_git_ssh_command() {
  local command="$1" applied="$2"
  if [[ "$applied" == 1 ]]; then
    write_env GIT_SSH_COMMAND "$command"
  elif [[ "$command" != "$(_existing GIT_SSH_COMMAND || true)" ]]; then
    SKIPPED+=("git push по SSH: изменение не применено, $OVERRIDE_FILE не перезаписан; запусти визард снова и согласись его перезаписать")
  fi
}

# Dry-run push from inside the running container: the check behind "agent can push". One push
# per ssh host in $KNOWN_HOSTS_FILE, from the first repository of WORKSPACE that pushes there;
# a host left out of it is already in SKIPPED. Not fatal, the result is only shown.
check_git_push_from_container() {
  local entry host port repo remote output line checked=0
  # The skip messages were shown in the "Git-доступ по SSH" stage.
  collect_ssh_hosts "$WORKSPACE" > /dev/null 2>&1
  if (( ${#SSH_HOSTS[@]} == 0 )); then
    note "push из контейнера не проверял: в $WORKSPACE нет репозиториев с ssh-remote"
    return 0
  fi
  for entry in "${SSH_HOSTS[@]}"; do
    read -r host port _ <<< "$entry"
    repo="${entry#* * }"
    [[ -f "$KNOWN_HOSTS_FILE" ]] \
      && ssh-keygen -F "$(known_hosts_name "$host" "$port")" -f "$KNOWN_HOSTS_FILE" > /dev/null 2>&1 \
      || continue
    checked=1
    remote=$(workspace_remote_name "$repo")
    step "git -C $repo push --dry-run $remote HEAD из контейнера"
    if output=$(docker compose exec -T opencode git -C "$repo" push --dry-run "$remote" HEAD 2>&1); then
      say "✓ push на $host проходит"
    else
      warn "push на $host не прошёл (визард на этом не останавливается):"
      while IFS= read -r line; do note "  ${line//[[:cntrl:]]/?}"; done <<< "$output"
    fi
  done
  if (( ! checked )); then
    note "push из контейнера не проверял: ни один ssh-хост репозиториев не попал в $KNOWN_HOSTS_FILE"
  fi
}

path_checksum() {
  printf '%s' "$1" | cksum | cut -d' ' -f1
}

# sha256_hex prints the sha256 of stdin in hex: sha256sum on Linux, shasum on macOS. Fails
# when the host has neither.
sha256_hex() {
  local digest
  if command -v sha256sum >/dev/null 2>&1; then
    digest=$(sha256sum)
  elif command -v shasum >/dev/null 2>&1; then
    digest=$(shasum -a 256)
  else
    return 1
  fi
  printf '%s' "${digest%% *}"
}

# path_tail PATH prints the readable part of a name: the tail of PATH in lowercase letters,
# digits and dashes.
path_tail() {
  local slug
  slug=$(printf '%s' "$1" | tr -c 'A-Za-z0-9' '-' | tr -s '-' | tr '[:upper:]' '[:lower:]')
  slug="${slug#-}"; slug="${slug%-}"
  slug="${slug: -40}"; slug="${slug#-}"
  printf '%s' "$slug"
}

# workspace_slug PATH prints a name suffix: a readable tail of PATH plus its checksum, so
# similar paths still get different names.
workspace_slug() {
  printf '%s-%s' "$(path_tail "$1")" "$(path_checksum "$1")"
}

# venv_volume_name WORKSPACE PROJECT names the volume over PROJECT/.venv. The hash covers the
# workspace too: a project seen from two overlapping workspaces gets two volumes, and their
# containers share no executables. A hash, not the checksum: the names are global and the
# agent picks the project paths, and a CRC collision is forged in milliseconds, which would
# mount another workspace's .venv. Fails without a sha256 tool.
venv_volume_name() {
  local workspace="$1" project="$2" hash
  hash=$(printf '%s\n%s' "$workspace" "$project" | sha256_hex) || return 1
  (( ${#hash} >= VENV_HASH_LENGTH )) || return 1
  printf 'opencode-venv-%s-%s' "$(path_tail "$project")" "${hash:0:VENV_HASH_LENGTH}"
}

# prepare_venv_overlays WORKSPACE fills VENV_OVERLAYS with "VOLUME TARGET" for the .venv of
# every top python project, creates a missing host .venv as the mount point (otherwise
# Docker creates it, as root on Linux) and prints the projects with the re-run warning.
prepare_venv_overlays() {
  local workspace="$1" project volume
  VENV_OVERLAYS=()
  while IFS= read -r project; do
    if [[ ! -e "$project/.venv" ]]; then
      mkdir "$project/.venv" || warn "не смог создать $project/.venv: создай её сам, иначе Docker сделает её от root"
    fi
    if ! volume=$(venv_volume_name "$workspace" "$project"); then
      warn "на хосте нет ни sha256sum, ни shasum: не могу назвать .venv-volume для $project"
      return 1
    fi
    VENV_OVERLAYS+=("$volume $project/.venv")
  done < <(python_projects "$workspace")
  show_python_projects "$workspace"
  warn "появился новый питон-проект — перезапусти визард. Без этого у него нет своего"
  warn ".venv в контейнере, и контейнерный uv sync перезапишет его хостовый .venv."
}

# show_python_projects WORKSPACE prints the python projects in VENV_OVERLAYS relative to
# WORKSPACE.
show_python_projects() {
  local workspace="$1" project
  if (( ${#VENV_OVERLAYS[@]} == 0 )); then
    say "Питон-проектов в $workspace не нашёл."
  else
    say "Питон-проекты, у каждого свой .venv в контейнере:"
    for project in "${VENV_OVERLAYS[@]}"; do
      project="${project#* }"
      project="${project%/.venv}"
      project="${project#"$workspace"}"
      if [[ -z "$project" ]]; then
        step ". (вся рабочая папка)"
      else
        step "${project#/}"
      fi
    done
  fi
}

home_volume_name() {
  printf 'opencode-home-%s' "$(workspace_slug "$1")"
}

compose_project_name() {
  printf 'opencode-%s' "$(workspace_slug "$1")"
}

# A stable port per repository, so two repositories set up one after another don't both
# ask for 4096. lsof in the port stage still catches a collision with anything else.
workspace_port() {
  printf '%s' $(( WORKSPACE_PORT_FIRST + $(path_checksum "$1") % WORKSPACE_PORT_COUNT ))
}

# Writes the compose project, the .venv and home volumes and, for a new repository, its port
# to .env. The home volume holds the opencode binary and ~/.local/bin, which the agent can
# write: a home shared between repositories lets an agent in one plant code that runs in
# another with that repository's deploy key. HOME_VOLUME stays shared only when it is set
# to the shared name by hand.
# A re-run on the same repository keeps the saved project and port. A setup made before
# project names were derived runs as project `opencode`: renaming it would leave that
# container running beside the new one on the same port.
save_workspace_identity() {
  local workspace="$1" saved_workspace="$2" project home_before home_volume
  home_before=$(_existing HOME_VOLUME || true)
  if [[ "$workspace" == "$saved_workspace" ]]; then
    project=$(_existing COMPOSE_PROJECT_NAME || true)
    write_env COMPOSE_PROJECT_NAME "${project:-$LEGACY_PROJECT_NAME}"
  else
    write_env COMPOSE_PROJECT_NAME "$(compose_project_name "$workspace")"
    write_env OPENCODE_PORT "$(workspace_port "$workspace")"
  fi
  # The .venv volumes, one per python project, live in $OVERRIDE_FILE: compose reads no VENV_VOLUME.
  drop_env VENV_VOLUME
  if [[ "$home_before" == "$SHARED_HOME_VOLUME" ]]; then
    write_env HOME_VOLUME "$SHARED_HOME_VOLUME"
    return 0
  fi
  home_volume=$(home_volume_name "$workspace")
  write_env HOME_VOLUME "$home_volume"
  if [[ -z "$home_before" && -n "$saved_workspace" ]]; then
    note "Домашняя папка контейнера теперь своя у каждой рабочей папки: логин в провайдерах и загрузка opencode повторятся."
    note "Чтобы оставить общую, пропиши в .env HOME_VOLUME=$SHARED_HOME_VOLUME. Риск: агент в одной рабочей папке сможет подложить код, который запустится в другой."
    note "В старой общей $SHARED_HOME_VOLUME могла остаться подложенная закладка и токены всех провайдеров: когда все рабочие папки перейдут, считай её недоверенной и удали (docker volume rm $SHARED_HOME_VOLUME)."
  elif [[ -n "$home_before" && "$home_before" != "$home_volume" ]]; then
    note "HOME_VOLUME=$home_before заменён на $home_volume: логин и бинарь из старого volume больше не используются. Общую домашку можно оставить только именем $SHARED_HOME_VOLUME."
  fi
}

# Prints a warning when the workspace folder is itself a git repository that holds nested
# ones: opencode #51191 moves sessions started in a subfolder of a repository to its root.
# Prints nothing for a single repository or for a plain folder of repositories.
warn_nested_repositories() {
  local workspace="$1"
  [[ -e "$workspace/.git" ]] || return 0
  workspace_dirs_with "$workspace" .git | grep -qvxF "$workspace" || return 0
  warn "$workspace сам git-репозиторий, и внутри есть вложенные репозитории."
  note "Из-за бага opencode #51191 сессии из подпапки уедут в корень репозитория."
  note "Сделай рабочей папкой родителя без собственного .git или вынеси вложенные репозитории."
}

# Replaces the corporate apt setup in $APT_CONFIG_DIR with the files from SRC (a host
# folder): *.sources, *.list, *.conf, *.crt. With no SRC only clears it. The Dockerfile
# applies whatever lies there before the first apt-get. Fails when SRC has none of them.
install_apt_config() {
  local src="${1:-}" file copied=0
  if [[ -n "$src" && ! -d "$src" ]]; then
    warn "папки $src нет"
    return 1
  fi
  find "$APT_CONFIG_DIR" -mindepth 1 -maxdepth 1 ! -name README.md -exec rm -rf {} +
  [[ -n "$src" ]] || return 0
  for file in "$src"/*.sources "$src"/*.list "$src"/*.conf "$src"/*.crt; do
    [[ -f "$file" ]] || continue
    cp "$file" "$APT_CONFIG_DIR/"
    copied=$((copied + 1))
  done
  if (( copied == 0 )); then
    warn "в $src нет ни *.sources, ни *.list, ни *.conf, ни *.crt"
    return 1
  fi
  say "✓ скопировал в $APT_CONFIG_DIR файлов: $copied"
}

# normalize_apt_packages LIST prints LIST sorted bytewise, without duplicates, single-spaced.
# It goes into the image as a build argument, and the same set in another order would miss
# the layer cache.
normalize_apt_packages() {
  printf '%s' "$1" | tr -s '[:space:]' '\n' | sed '/^$/d' | LC_ALL=C sort -u | paste -sd' ' -
}

run_wizard() {

TOTAL_STAGES=11

cd "$(dirname "$0")/.."

banner "opencode в Docker: настройка и запуск"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Проверка окружения"
if ! command -v docker >/dev/null 2>&1; then
  warn "docker не найден. Поставь Docker-движок и запусти визард снова. Рекомендую colima:"
  note "  brew install colima docker docker-compose"
  note "Подойдут и OrbStack или Docker Desktop."
  exit 1
fi
if ! docker compose version >/dev/null 2>&1; then
  warn "нет docker compose v2 (команда docker compose). Обнови Docker и запусти визард снова."
  note "На colima: brew install docker-compose и подключи плагин, как скажет brew."
  exit 1
fi
choose_engine
engine_profile "$ENGINE" ""
COLIMA_PROFILE=$(colima_profile)
if docker info >/dev/null 2>&1; then
  say "✓ движок: $ENGINE_TITLE"
elif (( ENGINE_IS_COLIMA )); then
  say "colima установлена, но не запущена. Команду запуска дам после выбора рабочей папки:"
  say "ей нужен путь к ней, иначе контейнер её не увидит."
else
  warn "Docker-демон не отвечает. Запусти свой движок (colima, OrbStack, Docker Desktop) и запусти визард снова."
  exit 1
fi
say "✓ $(docker compose version)"
write_env DOCKER_ENGINE "$ENGINE"

HOST_OPENCODE_CONFIG="$HOME/.config/opencode"
if [[ -d "$HOST_OPENCODE_CONFIG" ]]; then
  say "✓ конфиг opencode: $HOST_OPENCODE_CONFIG"
else
  warn "не нашёл $HOST_OPENCODE_CONFIG"
  while true; do
    ask HOST_OPENCODE_CONFIG "Путь к папке с конфигом opencode:"
    HOST_OPENCODE_CONFIG=$(expand_path "$HOST_OPENCODE_CONFIG")
    [[ -d "$HOST_OPENCODE_CONFIG" ]] && break
    warn "папки $HOST_OPENCODE_CONFIG нет"
  done
  write_env HOST_OPENCODE_CONFIG "$HOST_OPENCODE_CONFIG"
fi

HOST_GITCONFIG="$HOME/.gitconfig"
if [[ -f "$HOST_GITCONFIG" ]]; then
  say "✓ git-конфиг: $HOST_GITCONFIG"
else
  warn "не нашёл $HOST_GITCONFIG. Контейнеру нужен git-конфиг с user.name и user.email."
  while true; do
    ask HOST_GITCONFIG "Путь к git-конфигу:"
    HOST_GITCONFIG=$(expand_path "$HOST_GITCONFIG")
    [[ -f "$HOST_GITCONFIG" ]] && break
    warn "файла $HOST_GITCONFIG нет. Создать его можно так: git config --global user.name \"Имя\""
  done
  write_env HOST_GITCONFIG "$HOST_GITCONFIG"
fi
pause "Enter, чтобы продолжить"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Рабочая папка"
say "Папка, в которой opencode будет работать: один репозиторий или папка с несколькими."
say "Контейнер видит её на запись по тому же абсолютному пути, что и на хосте."
say "Бери самую узкую папку: только репозитории одного уровня доверия, без личных"
say "файлов, dotfiles и чужих проектов."
warn "Внутри рабочей папки изоляции между репозиториями нет: агент из одного пишет в код,"
note ".git и читает ключи остальных. Разный уровень доверия разводится только разными"
note "рабочими папками, то есть разными контейнерами."
note "Харнесс (папка с этим визардом) не может лежать в рабочей папке, и рабочая папка в нём"
note "тоже: агент переписал бы его compose-файлы и скрипты."
saved_workspace=$(_existing WORKSPACE || true)
if [[ -n "$saved_workspace" && -d "$saved_workspace" ]]; then
  saved_workspace=$(cd "$saved_workspace" && pwd -P)
fi
choose_workspace "$(pwd -P)"
warn_nested_repositories "$WORKSPACE"
write_env WORKSPACE "$WORKSPACE"
save_workspace_identity "$WORKSPACE" "$saved_workspace"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Рабочая папка внутри движка"
engine_profile "$ENGINE" "$WORKSPACE"
if (( ENGINE_IS_COLIMA )); then
  ensure_colima_workspace "$WORKSPACE" || exit 1
else
  while IFS= read -r line; do say "$line"; done <<< "$ENGINE_MOUNT_NOTE"
fi
pause "Enter, чтобы продолжить"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Пароль сервера"
say "Им браузер входит в веб-интерфейс (логин opencode)."
if [[ -n "$(_existing OPENCODE_SERVER_PASSWORD || true)" ]] && ! confirm "Пароль уже задан. Сменить?"; then
  say "оставил текущий пароль"
else
  if confirm "Сгенерировать случайный?"; then
    OPENCODE_SERVER_PASSWORD=$(generate_password)
  else
    OPENCODE_SERVER_PASSWORD=""
    while [[ ${#OPENCODE_SERVER_PASSWORD} -lt 12 ]]; do
      ask_secret OPENCODE_SERVER_PASSWORD "Пароль (от 12 символов):"
    done
  fi
  write_env OPENCODE_SERVER_PASSWORD "$OPENCODE_SERVER_PASSWORD"
fi
OPENCODE_SERVER_PASSWORD=$(_existing OPENCODE_SERVER_PASSWORD)

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Порт, часовой пояс, время обновления"
note "Enter без ввода берёт значение в квадратных скобках."
port_default=$(_existing OPENCODE_PORT || printf '%s' "$DEFAULT_PORT")
while true; do
  ask OPENCODE_PORT "Порт на хосте [$port_default]:"
  OPENCODE_PORT="${OPENCODE_PORT:-$port_default}"
  [[ "$OPENCODE_PORT" =~ ^[0-9]+$ ]] && (( OPENCODE_PORT >= 1 && OPENCODE_PORT <= 65535 )) && break
  warn "порт должен быть числом от 1 до 65535"
done
if command -v lsof >/dev/null 2>&1 && lsof -nP -iTCP:"$OPENCODE_PORT" -sTCP:LISTEN >/dev/null 2>&1; then
  warn "порт $OPENCODE_PORT уже кто-то слушает. Если это не этот же контейнер, выбери другой."
  if confirm "Ввести другой порт?"; then
    OPENCODE_PORT=""
    while ! [[ "$OPENCODE_PORT" =~ ^[0-9]+$ ]]; do
      ask OPENCODE_PORT "Порт на хосте:"
    done
  fi
fi
write_env OPENCODE_PORT "$OPENCODE_PORT"

detected_tz=$(host_timezone)
ask TZ "Часовой пояс [$detected_tz]:"
TZ="${TZ:-$detected_tz}"
write_env TZ "$TZ"

while true; do
  ask OPENCODE_UPDATE_HOUR "Час ежедневной проверки обновлений, 0-23 [$DEFAULT_UPDATE_HOUR]:"
  OPENCODE_UPDATE_HOUR="${OPENCODE_UPDATE_HOUR:-$DEFAULT_UPDATE_HOUR}"
  [[ "$OPENCODE_UPDATE_HOUR" =~ ^[0-9]+$ ]] && (( OPENCODE_UPDATE_HOUR <= 23 )) && break
  warn "нужно число от 0 до 23"
done
write_env OPENCODE_UPDATE_HOUR "$OPENCODE_UPDATE_HOUR"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Базовый образ и пакеты"
say "Образ собирается из $DEFAULT_BASE_IMAGE. Если Docker Hub недоступен или тормозит,"
say "можно взять Debian, который уже скачан локально."
local_debian=$(docker images debian --format '{{.Repository}}:{{.Tag}}' 2>/dev/null | grep -v ':<none>$' || true)
if docker image inspect "$DEFAULT_BASE_IMAGE" >/dev/null 2>&1; then
  say "✓ $DEFAULT_BASE_IMAGE уже есть локально"
  write_env BASE_IMAGE "$DEFAULT_BASE_IMAGE"
elif [[ -n "$local_debian" ]]; then
  say "Локально есть: ${local_debian//$'\n'/ }"
  local_choice=$(printf '%s\n' "$local_debian" | grep -m1 -- '-slim$' || printf '%s\n' "$local_debian" | head -n1)
  if confirm "Собирать из локального $local_choice?"; then
    write_env BASE_IMAGE "$local_choice"
  else
    write_env BASE_IMAGE "$DEFAULT_BASE_IMAGE"
  fi
else
  note "Локального Debian нет, $DEFAULT_BASE_IMAGE скачается при сборке."
  write_env BASE_IMAGE "$DEFAULT_BASE_IMAGE"
fi

printf '\n'
say "В корпоративной сети deb.debian.org бывает закрыт, и пакеты идут через внутреннее"
say "зеркало. Тогда укажи папку с его apt-настройками: *.sources или *.list, *.conf"
say "(прокси, логин), *.crt. Визард скопирует их в $APT_CONFIG_DIR, подробности там в README.md."
while true; do
  ask APT_CONFIG_SOURCE "Папка с apt-настройками зеркала, Enter — стандартный Debian, «-» — убрать:"
  case "${APT_CONFIG_SOURCE:-}" in
    "")
      break
      ;;
    -)
      APT_CONFIG_SOURCE=""
      install_apt_config ""
      break
      ;;
    *)
      APT_CONFIG_SOURCE=$(expand_path "$APT_CONFIG_SOURCE")
      install_apt_config "$APT_CONFIG_SOURCE" && break
      ;;
  esac
done
write_env APT_CONFIG_SOURCE "$APT_CONFIG_SOURCE"

printf '\n'
say "Питон-профиль: $PYTHON_PROFILE_APT_PACKAGES (gcc для сборки колёс) и uv прямо в образ."
say "Системный питон не ставится: uv приносит свой при uv sync. У каждого питон-проекта"
say "в контейнере свой .venv поверх хостового, хостовый контейнер не видит и не трогает."
default_packages=""
configure_python_profile
if [[ "$INSTALL_UV" == 1 ]]; then
  default_packages="$PYTHON_PROFILE_APT_PACKAGES"
  say "Нативным зависимостям нужны dev-библиотеки: допиши их к профилю,"
  say "например: $PYTHON_PROFILE_APT_PACKAGES libpq-dev libffi-dev. Сам визард их не угадывает."
else
  say "Тулчейн проекта ставится apt-пакетами в образ."
fi
while true; do
  ask EXTRA_APT_PACKAGES "apt-пакеты через пробел [${default_packages:-без пакетов}], «-» — без них:"
  EXTRA_APT_PACKAGES="${EXTRA_APT_PACKAGES:-$default_packages}"
  [[ "$EXTRA_APT_PACKAGES" == "-" ]] && EXTRA_APT_PACKAGES=""
  [[ "$EXTRA_APT_PACKAGES" =~ ^[a-z0-9.+:\ -]*$ ]] && break
  warn "имена apt-пакетов: строчные буквы, цифры и . + - :"
done
write_env EXTRA_APT_PACKAGES "$(normalize_apt_packages "$EXTRA_APT_PACKAGES")"
printf '\n'
# Written to $OVERRIDE_FILE in the "Дополнительные папки" stage.
prepare_venv_overlays "$WORKSPACE"
pause "Enter, чтобы продолжить"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Владелец файлов"
if [[ "$(uname -s)" == "Linux" ]]; then
  say "На Linux контейнер должен работать под твоим UID и GID, иначе файлы в рабочей папке"
  say "будут принадлежать чужому пользователю."
  write_env OPENCODE_UID "$(id -u)"
  write_env OPENCODE_GID "$(id -g)"
else
  say "На macOS Docker сам сопоставляет владельца файлов, здесь настраивать нечего."
fi
pause "Enter, чтобы продолжить"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Git-доступ по SSH"
say "Чтобы агент мог пушить, в контейнер монтируется один выбранный ssh-ключ и known_hosts,"
say "оба только на чтение. git ходит этим ключом через GIT_SSH_COMMAND, твой ~/.gitconfig"
say "остаётся как есть."
# Collected here and in the next stage; the next stage writes the mounts to $OVERRIDE_FILE
# and only then GIT_SSH_COMMAND to .env.
extra_mounts=()
git_ssh_command=""
if ! confirm_default "$(saved_git_ssh_flag)" "Настроить git push по SSH?"; then
  say "пропускаю: агент сможет коммитить, но не пушить"
elif ! configure_git_ssh; then
  SKIPPED+=("git push по SSH: запусти визард снова, когда разберёшься с предупреждением выше")
fi
pause "Enter, чтобы продолжить"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Дополнительные папки и симлинки"
say "Конфиги монтируются только на чтение. Абсолютные симлинки в них работают, только если"
say "их цель смонтирована по тому же пути. Соберу $OVERRIDE_FILE с нужными папками."
scan_dirs=("$HOST_OPENCODE_CONFIG")
HOST_AGENTS_DIR="$HOME/.agents"
if [[ ! -d "$HOST_AGENTS_DIR" ]]; then
  while true; do
    HOST_AGENTS_DIR=""
    ask HOST_AGENTS_DIR "Папка с глобальными скиллами агента (обычно ~/.agents), Enter — нет такой, «-» — убрать:" || break
    case "$HOST_AGENTS_DIR" in
      "" | -) HOST_AGENTS_DIR=""; break ;;
    esac
    HOST_AGENTS_DIR=$(expand_path "$HOST_AGENTS_DIR")
    [[ -d "$HOST_AGENTS_DIR" ]] && break
    warn "папки $HOST_AGENTS_DIR нет"
  done
  write_env HOST_AGENTS_DIR "$HOST_AGENTS_DIR"
fi
if [[ -n "$HOST_AGENTS_DIR" ]] && confirm "Подключить $HOST_AGENTS_DIR (глобальные скиллы)?"; then
  extra_mounts+=("$HOST_AGENTS_DIR:/home/opencode/.agents")
  scan_dirs+=("$HOST_AGENTS_DIR")
fi
if [[ -d "$HOME/.config/git" ]] && confirm "Подключить $HOME/.config/git (глобальный gitignore)?"; then
  extra_mounts+=("$HOME/.config/git:/home/opencode/.config/git")
fi
symlink_dirs=$(absolute_symlink_targets "${scan_dirs[@]}" | while IFS= read -r t; do mount_dir_for_target "$t"; printf '\n'; done | drop_nested_paths)
if [[ -n "$symlink_dirs" ]]; then
  say "Цели симлинков, которые смонтирую по тому же пути:"
  while IFS= read -r dir; do
    step "$dir"
    extra_mounts+=("$dir:$dir")
  done <<< "$symlink_dirs"
else
  say "Абсолютных симлинков не нашёл."
fi

override_applied=1
apply_override ${extra_mounts[@]+"${extra_mounts[@]}"} || override_applied=0
save_git_ssh_command "$git_ssh_command" "$override_applied"
pause "Enter, чтобы продолжить"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Сервисы на хосте"
say "Внутри контейнера 127.0.0.1 и localhost означают сам контейнер. Если конфиг opencode"
say "ходит в локальный прокси или MCP-сервер на хосте, порт надо пробросить на хост."
found_ports=$(config_loopback_ports "$HOST_OPENCODE_CONFIG")
if [[ -n "$found_ports" ]]; then
  say "В конфиге нашёл локальные порты:"
  for port in ${found_ports//,/ }; do
    if command -v lsof >/dev/null 2>&1 && lsof -nP -iTCP:"$port" -sTCP:LISTEN >/dev/null 2>&1; then
      step "$port: на хосте его сейчас слушают"
    else
      step "$port: на хосте сейчас никто не слушает, запусти сервис до работы с opencode"
    fi
  done
else
  say "Локальных адресов в конфиге не нашёл."
fi
configure_host_ports "$found_ports"
pause "Enter, чтобы продолжить"

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Сборка и запуск"
server_url="http://localhost:$OPENCODE_PORT"
say "Соберу образ и подниму контейнер. При первом запуске он скачивает opencode с npm,"
say "это может занять несколько минут."
if ! confirm_default 1 "Запускать?"; then
  SKIPPED+=("запуск: docker compose up -d --build")
else
  # The failure branches pause: finish clears the screen, and the error would go with it.
  if ! docker compose up -d --build; then
    warn "сборка или запуск упали, вывод выше. Полный лог сборки по шагам:"
    say "  docker compose --progress plain build"
    SKIPPED+=("запуск: разберись с ошибкой и повтори docker compose up -d --build")
    pause "Enter, когда прочитал ошибку"
  elif ! wait_until_ready "$server_url/"; then
    warn "сервер не ответил за $((HEALTH_TIMEOUT_SECONDS / 60)) минут. Последние строки лога:"
    docker compose logs --tail 30 || true
    SKIPPED+=("запуск: смотри docker compose logs -f")
    pause "Enter, когда прочитал лог"
  else
    if [[ "$(saved_git_ssh_flag)" == 1 ]]; then
      check_git_push_from_container
    fi
    say "Логин в браузере: opencode"
    if printf '%s' "$OPENCODE_SERVER_PASSWORD" | copy_to_clipboard 2>/dev/null; then
      say "Пароль скопирован в буфер обмена."
    else
      say "Пароль лежит в .env, строка OPENCODE_SERVER_PASSWORD."
    fi
    open_url "$server_url"
    pause "Enter, когда вошёл"
  fi
fi

finish
say "Веб-интерфейс: $server_url  (логин opencode, пароль в .env)"
say "Ключи провайдеров хранятся в базе opencode, а не в конфиге. Если их нет в opencode.jsonc,"
say "подключи провайдера в веб-интерфейсе."
say "Лог: docker compose logs -f    Остановить: docker compose down"
printf '\n'
show_python_projects "$WORKSPACE"
printf '\n'
}

run_wizard "$@"; exit
